internal record ControlsInspection(string DeformChecksum,ControlRigSetup[] ControlRigs,ContactFrame[] Contacts,int BodyBone,Transform[] KeyedPose,System.Numerics.Vector3[] BonePositions,System.Numerics.Quaternion[] BoneRotations,int? SampleCount,bool? NativeLoop);
