internal record MorphProjectInspection(MorphLayerInspection[] NativeLayers,NativeResourceEntry[] NativeResources);
internal record MorphGeometryInspection(int Mesh,string Name,int Count,System.Numerics.Vector4[] Points,bool GeometryEdited,NativeResourceRef? Native,NativeResourceRef Basis);
internal static class CliRetarget
{
    public static RetargetBake Accept(FighterProject target,ControlRigSetup rig,OperationResult<RetargetBake> output,string[] args)
    {
        var bake=output.Value??throw new InvalidDataException("No candidate result.");var validation=RetargetAcceptance.Measure(target,rig,bake);bool reviewed=args.Contains("--review-channel-losses");bool ready=RetargetAcceptance.Ready(validation,output.Diagnostics,output.LostChannels,reviewed);
        if(!ready&&!args.Contains("--allow-review-draft")&&!args.Contains("--fk-only"))throw new InvalidOperationException($"Target pose/contact/context acceptance remains open: separation {validation.Separation:G6}/{validation.PositionBound:G6}, penetration {validation.Penetration:G6}/{validation.PenetrationBound:G6}. Use library-use-selected --preview-only for receipts. --allow-review-draft explicitly creates an unvalidated editable draft; --review-channel-losses accepts reported skeletal-transfer losses only.");
        return bake with{Clip=bake.Clip with{Retarget=bake.Clip.Retarget! with{Validation=validation,ChannelLossesReviewed=reviewed,IsDraft=!ready}}};
    }
}
